  tools/api.py GET  /v1/mailbox/messages/275/attachments/3 --out shipments/275/packing.pdf
  tools/api.py POST /v1/mailbox/messages '{"to":"x@hackloop.mail","subject":"..","body":"..","in_reply_to":275}'
